import React from "react";
import { Link } from "react-router-dom";
import SeverityBadge from "../ui/SeverityBadge";
import StatusBadge from "../ui/StatusBadge";

const headings = [
  "CASE ID",
  "CATEGORY",
  "SEVERITY",
  "STATUS",
  "LOCATION",
  "DATE REPORTED",
  "ASSIGNED TO",
  "",
];

const ReportsTable = ({ reports }) => (
  <div className="overflow-x-auto">
    <table className="w-full min-w-[940px] border-collapse text-left">
      <thead className="bg-gray-50 text-[8px] font-bold tracking-wide text-gray-400">
        <tr>
          {headings.map((heading, index) => (
            <th className="px-3 py-3" key={`${heading}-${index}`}>
              {heading}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {reports.map((report) => (
          <tr
            className="border-t border-gray-100 text-[9px] text-gray-600 hover:bg-gray-50"
            key={report.id}
          >
            <td className="px-3 py-3.5">
              <Link
                className="font-bold text-[#355d43] hover:underline"
                to={`/reports/${report.id}`}
              >
                {report.id}
              </Link>
            </td>
            <td className="px-3 py-3.5">{report.category}</td>
            <td className="px-3 py-3.5">
              <SeverityBadge severity={report.severity} />
            </td>
            <td className="px-3 py-3.5">
              <StatusBadge status={report.status} />
            </td>
            <td className="px-3 py-3.5 text-gray-500">⌖ {report.location}</td>
            <td className="px-3 py-3.5">{report.date}</td>
            <td className="px-3 py-3.5">
              {report.officer === "Unassigned" ? (
                <span className="text-amber-700">Unassigned</span>
              ) : (
                report.officer
              )}
            </td>
            <td className="px-3 py-3.5">
              <Link
                aria-label={`Open ${report.id}`}
                className="text-lg text-gray-500"
                to={`/reports/${report.id}`}
              >
                ···
              </Link>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
    {reports.length === 0 && (
      <div className="p-10 text-center text-xs text-gray-500">
        No reports match these filters.
      </div>
    )}
  </div>
);

export default ReportsTable;
